import React from "react";
import PageWrapper from "../PageWrapper";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";

const Home = () => {
  const navigate = useNavigate();
  return (
    <PageWrapper>
      <div className="min-h-[80vh] flex flex-col items-center justify-center text-center px-6 bg-gradient-to-br from-blue-50 to-indigo-100">
        <motion.h1
          initial={{ y: -30, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="text-5xl font-bold text-blue-800 mb-4"
        >
          Ready to Practice?
        </motion.h1>
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
          className="text-gray-600 max-w-lg mb-6"
        >
          Take a mock interview session with our AI — record or upload a video and receive instant insights.
        </motion.p>
        <motion.button
          whileHover={{ scale: 1.05 }}
          onClick={() => navigate("/interview")}
          className="bg-indigo-600 text-white px-8 py-3 rounded-full hover:bg-indigo-700 transition"
        >
          Go to Interview
        </motion.button>
      </div>
    </PageWrapper>
  );
};

export default Home;
